args.content:
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    line-height: 1.6;
    color: #333;
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

header {
    margin-bottom: 3rem;
    border-bottom: 2px solid #2c5282;
    padding-bottom: 1rem;
}

h1 {
    font-size: 2.5rem;
    color: #2c5282;
    margin-bottom: 0.5rem;
}

.tagline {
    font-size: 1.1rem;
    color: #666;
    font-style: italic;
}

section {
    margin-bottom: 2.5rem;
}

h2 {
    font-size: 1.8rem;
    color: #2c5282;
    margin-bottom: 1rem;
}

p {
    margin-bottom: 1rem;
}

ul {
    margin-left: 2rem;
    margin-bottom: 1rem;
}

li {
    margin-bottom: 0.5rem;
}

strong {
    color: #2c5282;
}

footer {
    margin-top: 4rem;
    padding-top: 2rem;
    border-top: 1px solid #ddd;
    color: #666;
    font-size: 0.9rem;
}

footer a {
    color: #2c5282;
    text-decoration: none;
}

footer a:hover {
    text-decoration: underline;
}

.updated {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #999;
}

@media (max-width: 600px) {
    body {
        padding: 1rem;
    }

    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }
}
